description:
Implement a `useThrottleFn` hook that returns a throttled version of `fn`. The throttled function fires immediately on the first call and ignores subsequent calls within the `limit` ms window.

**Example:**
```tsx
const throttledScroll = useThrottleFn(handleScroll, 100);
window.addEventListener('scroll', throttledScroll);
```

starter_code:
import { useCallback, useRef } from 'react';

export function useThrottleFn<T extends unknown[]>(
  fn: (...args: T) => void,
  limit: number
): (...args: T) => void {
  // your code here
}

test_suite:
test('fires immediately on first call', () => {
  vi.useFakeTimers();
  const fn = vi.fn();
  const { result } = renderHook(() => useThrottleFn(fn, 200));
  act(() => result.current());
  expect(fn).toHaveBeenCalledTimes(1);
  vi.useRealTimers();
});

test('ignores calls within the limit window', () => {
  vi.useFakeTimers();
  const fn = vi.fn();
  const { result } = renderHook(() => useThrottleFn(fn, 200));
  act(() => result.current());
  act(() => result.current());
  act(() => result.current());
  expect(fn).toHaveBeenCalledTimes(1);
  vi.useRealTimers();
});

test('fires again after limit window expires', () => {
  vi.useFakeTimers();
  const fn = vi.fn();
  const { result } = renderHook(() => useThrottleFn(fn, 200));
  act(() => result.current());
  vi.advanceTimersByTime(200);
  act(() => result.current());
  expect(fn).toHaveBeenCalledTimes(2);
  vi.useRealTimers();
});

// __hidden__
test('always uses latest fn reference', () => {
  vi.useFakeTimers();
  let val = '';
  const { rerender, result } = renderHook(({ f }) => useThrottleFn(f, 200), {
    initialProps: { f: () => { val = 'old'; } }
  });
  rerender({ f: () => { val = 'new'; } });
  vi.advanceTimersByTime(200);
  act(() => result.current());
  expect(val).toBe('new');
  vi.useRealTimers();
});

solution:
import { useCallback, useRef } from 'react';

export function useThrottleFn<T extends unknown[]>(
  fn: (...args: T) => void,
  limit: number
): (...args: T) => void {
  const savedFn = useRef(fn);
  savedFn.current = fn;
  const lastRun = useRef<number>(0);

  return useCallback((...args: T) => {
    const now = Date.now();
    if (now - lastRun.current >= limit) {
      lastRun.current = now;
      savedFn.current(...args);
    }
  }, [limit]);
}
